// tb_astra07_hold.sv — compact held-out transfer XSim. PROGRAM=NO.
// Reuses a7ng_shared_rank_sgd_q8. Fixture mem generated by host_astra07.py.
`timescale 1ns / 1ps
`include "tb_astra07_params.svh"

module tb_astra07_hold;
  logic clk, rst_n, freeze, go_s, go_u, ready, done;
  logic signed [7:0]  x [0:A7_N-1];
  logic signed [2:0]  rew;
  logic signed [15:0] v;
  integer fail, i, q, k, t, pred, gold, ok, best, tmo;
  integer c_en, c_fr, c_sh, ngold, n_ans;
  logic signed [15:0] vs [0:A7_K-1];
  logic signed [15:0] ev;

  logic [255:0] tr_x_mem [0:A7_N_UPD-1];
  logic [7:0]   tr_r_mem [0:A7_N_UPD-1];
  logic [255:0] sh_x_mem [0:A7_N_UPD-1];
  logic [7:0]   sh_r_mem [0:A7_N_UPD-1];
  logic [255:0] ho_x_mem [0:A7_N_HOLD_Q*A7_K-1];
  logic [7:0]   ho_g_mem [0:A7_N_HOLD_Q-1];
  logic [15:0]  exp_en   [0:A7_N_HOLD_Q*A7_K-1];
  logic [15:0]  exp_sh   [0:A7_N_HOLD_Q*A7_K-1];
  logic [15:0]  exp_fr   [0:A7_N_HOLD_Q*A7_K-1];
  logic [255:0] miss_mem [0:A7_N_MISS_C-1];

  a7ng_shared_rank_sgd_q8 dut (
    .clk(clk), .rst_n(rst_n), .freeze_i(freeze),
    .go_score_i(go_s), .go_upd_i(go_u), .x_i(x), .reward_i(rew),
    .ready_o(ready), .done_o(done), .v_q8_o(v)
  );

  initial clk = 0;
  always #5 clk = ~clk;

  task automatic diverge(input string c, input string d);
    begin
      $display("FIRST_DIVERGENCE %s %s", c, d);
      fail = fail + 1;
      #20 $finish;
    end
  endtask

  task automatic unpack(input logic [255:0] p);
    integer j;
    begin
      for (j = 0; j < A7_N; j = j + 1)
        x[j] = p[255 - 8*j -: 8];
    end
  endtask

  task automatic kick(input int upd);
    begin
      while (!ready) @(posedge clk);
      @(posedge clk);
      go_s <= (upd == 0);
      go_u <= (upd != 0);
      @(posedge clk);
      go_s <= 1'b0;
      go_u <= 1'b0;
      tmo = 0;
      while (!done) begin
        @(posedge clk);
        tmo = tmo + 1;
        if (tmo > 4000) diverge("TIMEOUT", "");
      end
      @(posedge clk);
    end
  endtask

  task automatic rst_dut;
    begin
      rst_n = 0; freeze = 0; go_s = 0; go_u = 0; rew = 0;
      for (i = 0; i < A7_N; i = i + 1)
        x[i] = 8'sd0;
      repeat (4) @(posedge clk);
      rst_n = 1;
      repeat (2) @(posedge clk);
    end
  endtask

  task automatic train_stream(input int shuf);
    begin
      freeze = 0;
      for (t = 0; t < A7_N_UPD; t = t + 1) begin
        if (shuf) begin
          unpack(sh_x_mem[t]);
          rew = sh_r_mem[t][2:0];
        end else begin
          unpack(tr_x_mem[t]);
          rew = tr_r_mem[t][2:0];
        end
        kick(1);
      end
    end
  endtask

  task automatic score_hold(input string mode, input int check_exp, output integer n_ok);
    begin
      n_ok = 0;
      for (q = 0; q < A7_N_HOLD_Q; q = q + 1) begin
        best = -32768;
        pred = 0;
        for (k = 0; k < A7_K; k = k + 1) begin
          unpack(ho_x_mem[q*A7_K + k]);
          kick(0);
          vs[k] = v;
          if (check_exp) begin
            if (mode == "EN")
              ev = $signed(exp_en[q*A7_K + k]);
            else if (mode == "SH")
              ev = $signed(exp_sh[q*A7_K + k]);
            else
              ev = $signed(exp_fr[q*A7_K + k]);
            if (v !== ev)
              diverge("BITEXACT", $sformatf("%s q=%0d k=%0d v=%0d exp=%0d", mode, q, k, v, ev));
          end
          if (k == 0 || v > best) begin
            best = v;
            pred = k;
          end
        end
        gold = ho_g_mem[q];
        ok = (pred == gold);
        n_ok = n_ok + ok;
        $display("ASTRA07_HOLD_PICK mode=%s q=%0d pred=%0d gold=%0d ok=%0d best=%0d",
                 mode, q, pred, gold, ok, best);
      end
    end
  endtask

  initial begin
    fail = 0;
    $readmemh("train_x.mem", tr_x_mem);
    $readmemh("train_r.mem", tr_r_mem);
    $readmemh("shuf_x.mem", sh_x_mem);
    $readmemh("shuf_r.mem", sh_r_mem);
    $readmemh("hold_x.mem", ho_x_mem);
    $readmemh("hold_gold.mem", ho_g_mem);
    $readmemh("exp_hold_v_en.mem", exp_en);
    $readmemh("exp_hold_v_sh.mem", exp_sh);
    $readmemh("exp_hold_v_fr.mem", exp_fr);
    $readmemh("miss_x.mem", miss_mem);

    rst_dut;
    freeze = 1;
    unpack(ho_x_mem[0]);
    kick(0);
    if (v !== 16'sd0)
      diverge("ZERO_WEIGHT", $sformatf("v=%0d", v));
    $display("T_FROZEN_ZERO v=%0d", v);

    freeze = 1;
    score_hold("FR", 1, c_fr);
    $display("ASTRA07_FR_HOLDCORRECT n=%0d c=%0d", A7_N_HOLD_Q, c_fr);

    rst_dut;
    train_stream(0);
    freeze = 1;
    score_hold("EN", 1, c_en);
    $display("ASTRA07_EN_HOLDCORRECT n=%0d c=%0d", A7_N_HOLD_Q, c_en);

    ngold = 0;
    n_ans = 0;
    for (k = 0; k < A7_N_MISS_C; k = k + 1) begin
      unpack(miss_mem[k]);
      kick(0);
      if (x[31] === 8'sd127)
        ngold = ngold + 1;
      $display("ASTRA07_MISS_V k=%0d v=%0d f31=%0d", k, v, x[31]);
    end
    if (ngold != 0)
      diverge("MISS_GOLD_PRESENT", $sformatf("ngold=%0d", ngold));
    n_ans = 0;
    $display("ASTRA07_MISS ngold=%0d n_ans=%0d n_c=%0d", ngold, n_ans, A7_N_MISS_C);

    rst_dut;
    train_stream(1);
    freeze = 1;
    score_hold("SH", 1, c_sh);
    $display("ASTRA07_SH_HOLDCORRECT n=%0d c=%0d", A7_N_HOLD_Q, c_sh);

    if (c_en <= c_fr)
      diverge("TRANSFER_FROZEN", $sformatf("en=%0d fr=%0d", c_en, c_fr));
    if (c_en <= c_sh)
      diverge("TRANSFER_SHUFFLE", $sformatf("en=%0d sh=%0d", c_en, c_sh));

    $display("ASTRA07_BITEXACT_PASS");
    $display("ASTRA07_XSIM_PASS");
    $display("NOT_CLAIMED=open_world,board,lm,gate14");
    #20 $finish;
  end
endmodule
